from ute_wtssim.client.telnetclient import TelnetClient

from ta_egate_cmd_parser.egate_connection_registry import get_ta_egate_connection


class EgateConnection(object):
    """
    Class responsible for creating connection to EGATE.
    """

    def __init__(self, host, port):
        """

        :param host: IP address of host on which EGATE was started
        :param port: EGATE port
        """
        self.connection = TelnetClient(host=host, port=port, prompt='EGATE>')
        self.connection.open_connection()

    def read_until_regexp(self, regexp, timeout):
        """

        :param regexp:
        :param timeout:
        :return:
        """
        output = ""
        status = False
        try:
            status, output = self.connection.read_until_regexp(regexp=regexp, timeout=timeout)
        except Exception:
            print('Cannot read, probably socket closed')
        return status, output

    def close(self):
        """
        Specific close method handling the exception when close invoked multiple times from different threads.

        :return:
        """
        try:
            self.connection.close_connection()
        except Exception:
            pass


def get_connection(egate_id):
    """
    Return connection singleton

    :return:
    """
    egate_params = get_ta_egate_connection(egate_id)
    return EgateConnection(host=egate_params["host"], port=egate_params["port"])
